package org.codex.nfsugpreview;
import android.app.*;import android.os.*;import android.opengl.*;import java.io.*;import java.nio.*;import java.nio.file.*;import org.json.*;
public class MenuTextGpuInstrumentation extends SceneGpuInstrumentation {
 long checks,covered,transparent;
 String verify(NativeMenuText text,byte[] expected,int width,int height,int active)throws Exception{
 int[] id={0};GLES20.glGenTextures(1,id,0);int tex=id[0];GLES20.glBindTexture(GLES20.GL_TEXTURE_2D,tex);GLES20.glTexImage2D(GLES20.GL_TEXTURE_2D,0,GLES20.GL_RGBA,width,height,0,GLES20.GL_RGBA,GLES20.GL_UNSIGNED_BYTE,null);GLES20.glGenFramebuffers(1,id,0);int fbo=id[0];GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER,fbo);GLES20.glFramebufferTexture2D(GLES20.GL_FRAMEBUFFER,GLES20.GL_COLOR_ATTACHMENT0,GLES20.GL_TEXTURE_2D,tex,0);ok(GLES20.glCheckFramebufferStatus(GLES20.GL_FRAMEBUFFER)==GLES20.GL_FRAMEBUFFER_COMPLETE,"text framebuffer");GLES20.glDisable(GLES20.GL_SCISSOR_TEST);GLES20.glColorMask(true,true,true,true);GLES20.glClearColor(17/255f,34/255f,51/255f,1);GLES20.glClear(GLES20.GL_COLOR_BUFFER_BIT);
 try(NativeMenuTextGpu gpu=new NativeMenuTextGpu()){gpu.draw(text,active,height);}ByteBuffer actual=ByteBuffer.allocateDirect(width*height*4);GLES20.glReadPixels(0,0,width,height,GLES20.GL_RGBA,GLES20.GL_UNSIGNED_BYTE,actual);ok(GLES20.glGetError()==0,"text readback");
 for(int y=0;y<height;y++)for(int x=0;x<width;x++){int sy=Math.min(159,(int)(((height-y-.5)*160)/height)),sx=Math.min(239,(int)(((x+.5)*240)/active)),source=(sy*240+sx)*4,at=(y*width+x)*4;boolean glyph=x<active&&(expected[source+3]&255)>0;for(int c=0;c<4;c++){int want=glyph?expected[source+c]&255:(c==3?255:(c+1)*17);if((actual.get(at+c)&255)!=want)throw new AssertionError("text pixel "+x+","+y+" channel "+c);}checks++;if(glyph)covered++;else transparent++;}
 String hash=digest(actual);GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER,0);GLES20.glDeleteFramebuffers(1,new int[]{fbo},0);GLES20.glDeleteTextures(1,new int[]{tex},0);return hash;
 }
 @Override public void onStart(){Bundle result=new Bundle();boolean live=false;try{File dir=new File(getTargetContext().getFilesDir(),"menu-text-fixtures");NativeMenuText text=new NativeMenuText(Files.readAllBytes(new File(dir,"menu-4-positive.nft").toPath()),Files.readAllBytes(new File(dir,"menu-4-positive.nmp").toPath()));byte[] expected=Files.readAllBytes(new File(dir,"menu-text.rgba").toPath());startGl();live=true;String small=verify(text,expected,240,160,240),large=verify(text,expected,3840,2160,3240);endGl();live=false;startGl();live=true;ok(verify(text,expected,240,160,240).equals(small),"text context recreation");ok(covered>0&&transparent>0,"text branch coverage");JSONObject report=new JSONObject();report.put("result","PASS_ANDROID_MENU_TEXT_GPU");report.put("pixel_checks",checks);report.put("covered_samples",covered);report.put("transparent_samples",transparent);report.put("native_sha256",small);report.put("four_k_sha256",large);report.put("context_recreated",true);report.put("renderer",renderer);report.put("game_steps",0);try(FileOutputStream out=getTargetContext().openFileOutput("menu-text-gpu-report.json",0)){out.write(report.toString(2).getBytes("UTF-8"));}result.putString("stream",report.toString());finish(Activity.RESULT_OK,result);}catch(Throwable e){android.util.Log.e("NFSUGMenuTextGPU","Failed",e);result.putString("stream","FAIL: "+e);finish(Activity.RESULT_CANCELED,result);}finally{if(live)endGl();}}
}
